<section x-show="activeNav==='weather'" x-cloak class="dedicated-page">
    <div class="dedicated-page-head"><div><span>Date proiect</span><h2>Locație și condiții meteo</h2><p>Condițiile selectate sunt folosite imediat de motorul de simulare.</p></div><div class="page-summary-pill"><b>28°</b><small x-text="weatherLabel"></small></div></div>
    <div class="weather-page-grid">
        <section class="solar-card location-card p-5"><div class="card-heading"><h2>Locația proiectului</h2><span class="count-badge">⌖</span></div><div class="location-visual"><span>⌖</span><i></i><div><b x-text="initial.project.city"></b><small x-text="initial.project.county+', România'"></small></div></div><dl class="page-details"><div><dt>Latitudine</dt><dd x-text="initial.project.latitude||'Nespecificată'"></dd></div><div><dt>Longitudine</dt><dd x-text="initial.project.longitude||'Nespecificată'"></dd></div><div><dt>Fus orar</dt><dd x-text="initial.system.timezone||'Europe/Bucharest'"></dd></div></dl></section>
        <section class="solar-card p-5"><div class="card-heading"><div><h2>Condiții meteo</h2><p>Alege vremea pentru simularea curentă</p></div></div><div class="weather-options"><template x-for="option in [{id:'clear',icon:'☀️',name:'Însorit'},{id:'partly_cloudy',icon:'⛅',name:'Parțial noros'},{id:'cloudy',icon:'☁️',name:'Noros'},{id:'rain',icon:'🌧️',name:'Ploaie'},{id:'fog',icon:'🌫️',name:'Ceață'},{id:'snow',icon:'🌨️',name:'Zăpadă'}]" :key="option.id"><button type="button" @click="weather=option.id;randomWeather=false;tick()" :class="weather===option.id&&!randomWeather&&'is-selected'"><span x-text="option.icon"></span><b x-text="option.name"></b></button></template></div><label class="random-weather-toggle"><span><b>Vreme variabilă automat</b><small>Condițiile se pot schimba pe parcurs</small></span><input type="checkbox" x-model="randomWeather" @change="tick()"></label></section>
    </div>
</section>
